use rmcp::{handler::server::wrapper::Parameters, model::{CallToolResult,ContentBlock}, schemars, tool, tool_router, ServiceExt, transport::stdio};
use serde::{Deserialize,Serialize};
use serde_json::{json,Value};
use std::{path::{Path,PathBuf},sync::{Arc,Mutex},collections::HashMap};
use tokio::{process::Command,sync::oneshot};
use uuid::Uuid;
use sha2::{Digest,Sha256};

#[derive(Clone)] struct Studio { root:PathBuf, active:Arc<Mutex<HashMap<String,oneshot::Sender<()>>>> }
#[derive(Debug,Deserialize,schemars::JsonSchema)] #[serde(deny_unknown_fields)] struct ProjectArg { project_id:String }
#[derive(Debug,Deserialize,schemars::JsonSchema)] #[serde(deny_unknown_fields)] struct StyleArg { style_id:String }
#[derive(Debug,Deserialize,schemars::JsonSchema)] #[serde(deny_unknown_fields)] struct CreateArg { project_id:String, style_id:String }
#[derive(Debug,Deserialize,Serialize,schemars::JsonSchema)] #[serde(deny_unknown_fields)] struct Line { id:String,text:String }
#[derive(Debug,Deserialize,schemars::JsonSchema)] #[serde(deny_unknown_fields)] struct ScriptArg { project_id:String, lines:Vec<Line> }
#[derive(Debug,Deserialize,Serialize,schemars::JsonSchema)] #[serde(deny_unknown_fields)] struct Caption { thai:String, english:String, highlight:String }
#[derive(Debug,Deserialize,Serialize,schemars::JsonSchema)] #[serde(deny_unknown_fields)] struct Shot { start:f64,end:f64,camera:String,effect:String,caption:Caption }
#[derive(Debug,Deserialize,Serialize,schemars::JsonSchema)] #[serde(deny_unknown_fields)] struct ShotPlan { version:u8,title:String,scene:String,duration:f64,shots:Vec<Shot> }
#[derive(Debug,Deserialize,schemars::JsonSchema)] #[serde(deny_unknown_fields)] struct PlanArg { project_id:String, plan:ShotPlan }
#[derive(Debug,Deserialize,schemars::JsonSchema)] #[serde(deny_unknown_fields)] struct JobArg { project_id:String, job_id:String }
#[derive(Debug,Deserialize,schemars::JsonSchema)] #[serde(deny_unknown_fields)] struct RenderArg { project_id:String, request_id:String }
#[derive(Debug,Deserialize,schemars::JsonSchema)] #[serde(deny_unknown_fields)] struct PreviewArg { project_id:String, request_id:String, at:f64 }
#[derive(Debug,Deserialize,schemars::JsonSchema)] #[serde(deny_unknown_fields)] struct VoiceArg { project_id:String, request_id:String, provider:String, confirm_local_compute:bool }
#[derive(Debug,Deserialize,schemars::JsonSchema)] #[serde(deny_unknown_fields)] struct AttachArg { project_id:String, voice_job_id:String, line_id:String, start:f64 }
#[derive(Debug,Deserialize,schemars::JsonSchema)] #[serde(deny_unknown_fields)] struct RetimeArg { project_id:String, voice_job_id:String }
fn safe_id(s:&str)->bool { !s.is_empty()&&s.len()<=64&&s.bytes().all(|c|c.is_ascii_lowercase()||c.is_ascii_digit()||c==b'-')&&s.as_bytes()[0].is_ascii_lowercase()&&!s.ends_with('-')&&!s.contains("--") }
fn jid(s:&str)->bool {Uuid::parse_str(s).is_ok() && s.len()==36}
fn read_json(p:&Path)->anyhow::Result<Value>{let b=std::fs::read(p)?;anyhow::ensure!(b.len()<=100_000,"file too large");Ok(serde_json::from_slice(&b)?)}
fn write_json(p:&Path,v:&Value)->anyhow::Result<()> { let tmp=p.with_extension(format!("tmp-{}",Uuid::new_v4()));std::fs::write(&tmp,serde_json::to_vec_pretty(v)?)?;std::fs::rename(tmp,p)?; Ok(()) }
fn subdir(base:&Path,name:&str)->anyhow::Result<PathBuf>{let p=base.join(name);std::fs::create_dir_all(&p)?;let p=p.canonicalize()?;anyhow::ensure!(p.starts_with(base),"directory outside project");Ok(p)}
async fn stop_child(child:&mut tokio::process::Child){#[cfg(unix)] if let Some(pid)=child.id(){unsafe{libc::kill(-(pid as i32),libc::SIGTERM);}}let _=child.kill().await;}
fn answer(r:anyhow::Result<Value>)->CallToolResult { match r {Ok(v)=>CallToolResult::success(vec![ContentBlock::text(json!({"ok":true,"data":v}).to_string())]),Err(e)=>CallToolResult::error(vec![ContentBlock::text(json!({"ok":false,"error":e.to_string()}).to_string())])} }
impl Studio {
 fn data(&self)->anyhow::Result<PathBuf>{let base=self.root.join("outputs/rust-mcp");std::fs::create_dir_all(&base)?;let p=base.canonicalize()?;anyhow::ensure!(p.starts_with(&self.root),"output root outside workspace");Ok(p)}
 fn project(&self,id:&str)->anyhow::Result<PathBuf>{anyhow::ensure!(safe_id(id),"invalid project id");let data=self.data()?;let base=data.join("projects").canonicalize()?;anyhow::ensure!(base.starts_with(&data),"projects outside root");let p=base.join(id).canonicalize()?;anyhow::ensure!(p.starts_with(base),"project outside root");Ok(p)}
 fn node(&self)->anyhow::Result<PathBuf>{for p in ["/opt/homebrew/bin/node","/usr/local/bin/node","/usr/bin/node"] {let p=PathBuf::from(p);if p.is_file(){return Ok(p)}}anyhow::bail!("Node not found in standard locations")}
 async fn validate(&self,plan:&Path)->anyhow::Result<()> {let out=Command::new(self.node()?).arg(self.root.join("pipelines/shot-plan-v1/cli.mjs")).arg("check").arg(plan).current_dir(&self.root).output().await?;anyhow::ensure!(out.status.success(),"plan validation failed: {}",String::from_utf8_lossy(&out.stderr).trim());Ok(())}
 async fn launch(&self,project_id:&str,request_id:&str,kind:&str,at:Option<f64>)->anyhow::Result<Value>{
  anyhow::ensure!(jid(request_id),"request_id must be a UUID");let project=self.project(project_id)?;let jobs=subdir(&project,"jobs")?;let receipt=jobs.join(format!("{request_id}.json"));
  let plan=project.join("plan.json");self.validate(&plan).await?;let planval=read_json(&plan)?;let digest=format!("{:x}",Sha256::digest(serde_json::to_vec(&planval)?));if receipt.exists(){let old=read_json(&receipt)?;anyhow::ensure!(old["kind"]==kind && old["at"]==json!(at) && old["plan_hash"]==digest,"request id belongs to a different action or plan");return Ok(old)}
  if let Some(t)=at {anyhow::ensure!(t.is_finite() && t>=0.0 && t<planval["duration"].as_f64().unwrap_or(0.0),"preview time out of range")}
  let runs=subdir(&project,"runs")?;let run=runs.join(request_id);std::fs::create_dir(&run)?;
  let build_slug=format!("rust-{}-{}",project_id,request_id);let built=self.root.join("outputs/shot-plan-v1").join(&build_slug);
  let build=Command::new(self.node()?).arg(self.root.join("pipelines/shot-plan-v1/cli.mjs")).arg("build").arg(&plan).arg(&build_slug).current_dir(&self.root).output().await?;
  anyhow::ensure!(build.status.success(),"could not build composition: {}",String::from_utf8_lossy(&build.stderr).trim());
  let artifact=if kind=="render" {run.join("video.mp4")} else {run.join("frames")};
  let mut command=Command::new(self.node()?);command.arg(self.root.join("node_modules/.bin/hyperframes"));
  if kind=="render" {command.arg("render").arg(&built).args(["--fps","30","--quality","draft","--workers","1","-o"]).arg(&artifact);} else {command.arg("snapshot").arg(&built).arg("--at").arg(at.unwrap().to_string()).arg("--no-end").arg("--describe").arg("false").arg("--output").arg(&artifact);}
  command.current_dir(&self.root).env_remove("GEMINI_API_KEY").stdin(std::process::Stdio::null()).stdout(std::process::Stdio::null()).stderr(std::process::Stdio::null()).kill_on_drop(true);#[cfg(unix)] command.process_group(0);
  let mut child=command.spawn()?;let value=json!({"job_id":request_id,"project_id":project_id,"kind":kind,"at":at,"plan_hash":digest,"status":"running","artifact":null});write_json(&receipt,&value)?;
  let (tx,mut rx)=oneshot::channel();self.active.lock().unwrap().insert(format!("{project_id}/{request_id}"),tx);let active=self.active.clone();let id=format!("{project_id}/{request_id}");let path=receipt.clone();let artifact_string=artifact.to_string_lossy().to_string();let is_preview=kind=="preview";
  tokio::spawn(async move {let status=tokio::select!{s=child.wait()=>{let valid=if is_preview{std::fs::read_dir(&artifact).ok().is_some_and(|mut entries|entries.any(|e|e.ok().is_some_and(|e|e.path().extension().is_some_and(|x|x=="png"))))}else{std::fs::metadata(&artifact).is_ok_and(|m|m.is_file()&&m.len()>0)};if s.is_ok_and(|s|s.success())&&valid{"completed"}else{"failed"}},_= &mut rx=>{stop_child(&mut child).await;"cancelled"}};let mut v=read_json(&path).unwrap_or(json!({}));v["status"]=json!(status);if status=="completed" {v["artifact"]=json!(artifact_string)}let _=write_json(&path,&v);active.lock().unwrap().remove(&id);});
  Ok(value)
 }
}
#[tool_router(server_handler)] impl Studio {
 #[tool(description="List available local styles and their approval status. Rendering support is separately indicated.")]
 async fn list_styles(&self)->CallToolResult {answer((||{let mut out=vec![];for entry in std::fs::read_dir(self.root.join("styles"))?{let p=entry?.path().join("style.json");if p.is_file(){let x=read_json(&p)?;out.push(json!({"id":x["id"],"name":x["name"],"status":x["status"],"render_supported":x["id"]=="jk-soft-story-motion-v2"}))}}Ok(json!(out))})())}
 #[tool(description="Read the local STYLE.md for a catalog style ID.")]
 async fn get_style_guide(&self,Parameters(a):Parameters<StyleArg>)->CallToolResult {answer((||{anyhow::ensure!(safe_id(&a.style_id),"invalid style id");let base=self.root.join("styles").canonicalize()?;let p=base.join(&a.style_id).canonicalize()?;anyhow::ensure!(p.starts_with(&base),"style outside root");let text=std::fs::read_to_string(p.join("STYLE.md"))?;anyhow::ensure!(text.len()<100_000,"guide too large");Ok(json!({"style_id":a.style_id,"guide":text}))})())}
 #[tool(description="Create a new isolated local project. Rendering currently supports only jk-soft-story-motion-v2.")]
 async fn create_project(&self,Parameters(a):Parameters<CreateArg>)->CallToolResult {answer((||{anyhow::ensure!(safe_id(&a.project_id),"invalid project id");anyhow::ensure!(a.style_id=="jk-soft-story-motion-v2","style unsupported by this renderer");let data=self.data()?;let base=data.join("projects");std::fs::create_dir_all(&base)?;let base=base.canonicalize()?;anyhow::ensure!(base.starts_with(data),"projects outside root");let p=base.join(&a.project_id);std::fs::create_dir(&p)?;write_json(&p.join("project.json"),&json!({"project_id":a.project_id,"style_id":a.style_id}))?;Ok(json!({"project_id":a.project_id}))})())}
 #[tool(description="Save narration lines with unique IDs for local voice synthesis.")]
 async fn set_script(&self,Parameters(a):Parameters<ScriptArg>)->CallToolResult {answer((||{let p=self.project(&a.project_id)?;anyhow::ensure!(!a.lines.is_empty()&&a.lines.len()<=20,"need 1..20 lines");let mut seen=std::collections::HashSet::new();for line in &a.lines{anyhow::ensure!(safe_id(&line.id)&&seen.insert(&line.id)&&!line.text.trim().is_empty()&&line.text.chars().count()<=500,"invalid line")}write_json(&p.join("script.json"),&serde_json::to_value(&a.lines)?)?;Ok(json!({"line_ids":a.lines.iter().map(|x|&x.id).collect::<Vec<_>>() }))})())}
 #[tool(description="Set and validate a v1 shot plan. Audio must be attached separately; scenes use only the supported JK window.")]
 async fn set_shot_plan(&self,Parameters(a):Parameters<PlanArg>)->CallToolResult {answer(async{let p=self.project(&a.project_id)?;let plan=serde_json::to_value(&a.plan)?;let candidate=p.join(format!("candidate-{}.json",Uuid::new_v4()));write_json(&candidate,&plan)?;let valid=self.validate(&candidate).await;let _=std::fs::remove_file(&candidate);valid?;write_json(&p.join("plan.json"),&plan)?;Ok(json!({"validated":true,"duration":a.plan.duration}))}.await)}
 #[tool(description="List local voice choices and cloud-provider limitations. No credentials are read or remote calls made.")]
 async fn list_voices(&self)->CallToolResult {answer(Ok(json!({"local_jk":{"voice":"approved-calm-male-v1","mode":"offline MLX, local model required"},"google":{"status":"unsupported in Rust server; requires credentials, verified price and explicit approval"},"elevenlabs":{"status":"unsupported in Rust server; requires credentials, verified price and explicit approval"}})))}
 #[tool(description="List supported voice providers and their configuration requirements, without inspecting credentials.")]
 async fn list_voice_providers(&self)->CallToolResult {answer(Ok(json!({"local-jk":{"synthesis":"offline local MLX; configured model required"},"google":{"synthesis":"not implemented"},"elevenlabs":{"synthesis":"not implemented"}})))}
 #[tool(description="List supported model families without making provider calls.")]
 async fn list_voice_models(&self)->CallToolResult {answer(Ok(json!({"local-jk":"pinned VoxCPM2 per shared/voice profile","google":"not connected","elevenlabs":"not connected; model and language compatibility not verified"})))}
 #[tool(description="Create a local frame-preview job; poll job_status. request_id must be a UUID.")]
 async fn preview_frame(&self,Parameters(a):Parameters<PreviewArg>)->CallToolResult {answer(self.launch(&a.project_id,&a.request_id,"preview",Some(a.at)).await)}
 #[tool(description="Create a local silent or locally voiced render job; poll job_status. request_id must be a UUID.")]
 async fn render_video(&self,Parameters(a):Parameters<RenderArg>)->CallToolResult {answer(self.launch(&a.project_id,&a.request_id,"render",None).await)}
 #[tool(description="Get a local job receipt. Running jobs from a stopped server are reported interrupted.")]
 async fn job_status(&self,Parameters(a):Parameters<JobArg>)->CallToolResult {answer((||{anyhow::ensure!(jid(&a.job_id),"invalid job id");let p=self.project(&a.project_id)?.join("jobs").join(format!("{}.json",a.job_id));let mut v=read_json(&p)?;if v["status"]=="running"&&!self.active.lock().unwrap().contains_key(&format!("{}/{}",a.project_id,a.job_id)){v["status"]=json!("interrupted");write_json(&p,&v)?}Ok(v)})())}
 #[tool(description="Cancel an active job owned by this running server.")]
 async fn cancel_job(&self,Parameters(a):Parameters<JobArg>)->CallToolResult {answer((||{anyhow::ensure!(jid(&a.job_id),"invalid job id");let p=self.project(&a.project_id)?.join("jobs").join(format!("{}.json",a.job_id));let v=read_json(&p)?;anyhow::ensure!(v["status"]=="running","job not running");let tx=self.active.lock().unwrap().remove(&format!("{}/{}",a.project_id,a.job_id)).ok_or_else(||anyhow::anyhow!("job not owned by current server"))?;let mut pending=v;pending["status"]=json!("cancellation_requested");write_json(&p,&pending)?;let _=tx.send(());Ok(json!({"status":"cancellation_requested"}))})())}
 #[tool(description="List completed local job artifact locations and metadata; no upload.")]
 async fn list_artifacts(&self,Parameters(a):Parameters<ProjectArg>)->CallToolResult {answer((||{let p=self.project(&a.project_id)?.join("jobs");let mut out=vec![];if p.exists(){for e in std::fs::read_dir(p)?{let r=read_json(&e?.path())?;if r["status"]=="completed"{out.push(r)}}}Ok(json!(out))})())}
 #[tool(description="Read metadata for a completed artifact inside the named project.")]
 async fn get_artifact(&self,Parameters(a):Parameters<JobArg>)->CallToolResult {answer((||{anyhow::ensure!(jid(&a.job_id),"invalid job id");let p=self.project(&a.project_id)?;let r=read_json(&p.join("jobs").join(format!("{}.json",a.job_id)))?;anyhow::ensure!(r["status"]=="completed","job is not completed");let raw=r["artifact"].as_str().ok_or_else(||anyhow::anyhow!("missing artifact"))?;let artifact=PathBuf::from(raw).canonicalize()?;anyhow::ensure!(artifact.starts_with(&p),"artifact outside project");let m=std::fs::metadata(&artifact)?;Ok(json!({"job_id":a.job_id,"path":artifact.to_string_lossy(),"kind":r["kind"],"bytes":if m.is_file(){Some(m.len())}else{None},"directory":m.is_dir()}))})())}
 #[tool(description="Start offline JK voice generation from saved script. Requires local MLX/model setup and explicit local compute confirmation; no cloud providers.")]
 async fn synthesize_voice(&self,Parameters(a):Parameters<VoiceArg>)->CallToolResult {answer(async{
  anyhow::ensure!(a.provider=="local-jk","cloud voice providers are not connected");anyhow::ensure!(a.confirm_local_compute,"confirm_local_compute is required");anyhow::ensure!(jid(&a.request_id),"request_id must be a UUID");
  let p=self.project(&a.project_id)?;let script=p.join("script.json");let lines=read_json(&script)?;let hash=format!("{:x}",Sha256::digest(serde_json::to_vec(&lines)?));let jobs=subdir(&p,"jobs")?;let receipt=jobs.join(format!("{}.json",a.request_id));
  if receipt.exists(){let old=read_json(&receipt)?;anyhow::ensure!(old["kind"]=="voice"&&old["script_hash"]==hash,"request id belongs to different work");return Ok(old)}
  let py=self.root.join(".venv/bin/python");anyhow::ensure!(py.is_file(),"local JK voice runtime not installed");let run=subdir(&p,"runs")?.join(&a.request_id);std::fs::create_dir(&run)?;let voice=run.join("voice");let frozen=run.join("script.json");write_json(&frozen,&lines)?;
  let mut command=Command::new(py);command.arg(self.root.join("shared/voice/scripts/narrate.py")).arg("--lines").arg(&frozen).arg("--out").arg(&voice).current_dir(&self.root).env("HF_HUB_OFFLINE","1").env("TRANSFORMERS_OFFLINE","1").stdin(std::process::Stdio::null()).stdout(std::process::Stdio::null()).stderr(std::process::Stdio::null()).kill_on_drop(true);#[cfg(unix)] command.process_group(0);
  let mut child=command.spawn()?;let value=json!({"job_id":a.request_id,"project_id":a.project_id,"kind":"voice","script_hash":hash,"status":"running","artifact":null});write_json(&receipt,&value)?;
  let (tx,mut rx)=oneshot::channel();let id=format!("{}/{}",a.project_id,a.request_id);self.active.lock().unwrap().insert(id.clone(),tx);let active=self.active.clone();let output=voice.to_string_lossy().to_string();tokio::spawn(async move{let state=tokio::select!{s=child.wait()=>if s.is_ok_and(|s|s.success())&&voice.join("audio_meta.json").is_file(){ "completed" }else{"failed"},_=&mut rx=>{stop_child(&mut child).await;"cancelled"}};let mut v=read_json(&receipt).unwrap_or(json!({}));v["status"]=json!(state);if state=="completed"{v["artifact"]=json!(output)}let _=write_json(&receipt,&v);active.lock().unwrap().remove(&id);});Ok(value)
 }.await)}
 #[tool(description="Attach one WAV line from a completed local voice job to the shot plan; uses manual start and existing shot timing, not forced alignment.")]
 async fn attach_voice(&self,Parameters(a):Parameters<AttachArg>)->CallToolResult {answer(async{
  anyhow::ensure!(jid(&a.voice_job_id)&&safe_id(&a.line_id),"invalid job or line id");anyhow::ensure!(a.start.is_finite()&&a.start>=0.0,"invalid start");let p=self.project(&a.project_id)?;let receipt=read_json(&p.join("jobs").join(format!("{}.json",a.voice_job_id)))?;anyhow::ensure!(receipt["status"]=="completed"&&receipt["kind"]=="voice","voice job not completed");
  let run=p.join("runs").join(&a.voice_job_id).canonicalize()?;anyhow::ensure!(run.starts_with(&p),"voice job outside project");let audio=run.join("voice").join(format!("{}.wav",a.line_id)).canonicalize()?;anyhow::ensure!(audio.starts_with(&run)&&audio.is_file(),"voice line outside job");let assets=subdir(&p,"assets")?;let name=format!("voice-{}-{}.wav",a.voice_job_id,a.line_id);let target=assets.join(&name);let mut dst=std::fs::OpenOptions::new().write(true).create_new(true).open(&target)?;std::io::copy(&mut std::fs::File::open(audio)?,&mut dst)?;
  let mut plan=read_json(&p.join("plan.json"))?;plan["audio"]=json!({"file":format!("assets/{name}"),"start":a.start,"volume":1});let candidate=p.join(format!("candidate-{}.json",Uuid::new_v4()));write_json(&candidate,&plan)?;let validation=self.validate(&candidate).await;let _=std::fs::remove_file(&candidate);if let Err(e)=validation {let _=std::fs::remove_file(target);return Err(e)}write_json(&p.join("plan.json"),&plan)?;Ok(json!({"attached":true,"alignment":"manual start and existing shot times; no forced alignment"}))
 }.await)}
 #[tool(description="Concatenate one local voice line per shot and retime shot boundaries to measured line durations. No word alignment or pauses are inferred.")]
 async fn retime_from_voice(&self,Parameters(a):Parameters<RetimeArg>)->CallToolResult {answer(async{
  anyhow::ensure!(jid(&a.voice_job_id),"invalid job id");let p=self.project(&a.project_id)?;let receipt=read_json(&p.join("jobs").join(format!("{}.json",a.voice_job_id)))?;anyhow::ensure!(receipt["kind"]=="voice"&&receipt["status"]=="completed","voice job not completed");
  let run=p.join("runs").join(&a.voice_job_id).canonicalize()?;anyhow::ensure!(run.starts_with(&p),"voice job outside project");let lines=read_json(&run.join("script.json"))?;let lines=lines.as_array().ok_or_else(||anyhow::anyhow!("invalid script"))?;let mut plan=read_json(&p.join("plan.json"))?;let shots=plan["shots"].as_array_mut().ok_or_else(||anyhow::anyhow!("invalid plan"))?;anyhow::ensure!(!lines.is_empty()&&lines.len()==shots.len()&&lines.len()<=20,"requires exactly one voice line per shot");
  let mut inputs=Vec::new();let mut elapsed=0.0;for (line,shot) in lines.iter().zip(shots.iter_mut()) {let id=line["id"].as_str().unwrap_or("");anyhow::ensure!(safe_id(id),"invalid line id");let f=run.join("voice").join(format!("{id}.wav")).canonicalize()?;anyhow::ensure!(f.starts_with(&run),"audio outside voice job");let probe=Command::new("/opt/homebrew/bin/ffprobe").args(["-v","error","-show_entries","format=duration","-of","default=noprint_wrappers=1:nokey=1"]).arg(&f).output().await?;anyhow::ensure!(probe.status.success(),"could not probe voice line");let d:f64=String::from_utf8_lossy(&probe.stdout).trim().parse()?;anyhow::ensure!(d.is_finite()&&d>=0.8,"voice line too short for shot plan");shot["start"]=json!(elapsed);elapsed+=d;shot["end"]=json!(elapsed);inputs.push(f)}anyhow::ensure!(elapsed<=60.0,"audio exceeds maximum duration");plan["duration"]=json!(elapsed);
  let assets=subdir(&p,"assets")?;let name=format!("retimed-{}.wav",Uuid::new_v4());let target=assets.join(&name);let mut ff=Command::new("/opt/homebrew/bin/ffmpeg");ff.args(["-nostdin","-v","error","-n"]);for f in &inputs{ff.arg("-i").arg(f);}let filter=format!("{}concat=n={}:v=0:a=1[out]",(0..inputs.len()).map(|i|format!("[{i}:a]")).collect::<String>(),inputs.len());ff.args(["-filter_complex",&filter,"-map","[out]","-c:a","pcm_s16le"]).arg(&target).stdin(std::process::Stdio::null());let out=ff.output().await?;anyhow::ensure!(out.status.success(),"audio concatenation failed");plan["audio"]=json!({"file":format!("assets/{name}"),"start":0,"volume":1});let candidate=p.join(format!("candidate-{}.json",Uuid::new_v4()));write_json(&candidate,&plan)?;let valid=self.validate(&candidate).await;let _=std::fs::remove_file(&candidate);if let Err(e)=valid{let _=std::fs::remove_file(target);return Err(e)}let revisions=subdir(&p,"revisions")?;std::fs::copy(p.join("plan.json"),revisions.join(format!("plan-before-{}.json",Uuid::new_v4())))?;write_json(&p.join("plan.json"),&plan)?;Ok(json!({"duration":elapsed,"shots":inputs.len(),"alignment":"measured line durations; not word alignment"}))
 }.await)}
}
#[tokio::main] async fn main()->anyhow::Result<()> {let root=if let Ok(v)=std::env::var("JK_STUDIO_ROOT"){PathBuf::from(v)}else{PathBuf::from(env!("CARGO_MANIFEST_DIR")).parent().unwrap().to_path_buf()}.canonicalize()?;let s=Studio{root,active:Arc::new(Mutex::new(HashMap::new()))};s.serve(stdio()).await?.waiting().await?;Ok(())}
#[cfg(test)] mod tests {
 use super::*;
 #[test] fn ids_are_bounded_and_not_paths(){for x in ["../secret","/tmp/a","a/b","-bad","a--b","a-"]{assert!(!safe_id(x),"{x}")}for x in ["demo","shot-1","a0"]{assert!(safe_id(x))}assert!(!safe_id(&"a".repeat(65)))}
 #[test] fn job_ids_must_be_uuids(){assert!(jid(&Uuid::new_v4().to_string()));assert!(!jid("../../secrets"));assert!(!jid("00000000-0000-0000-0000-000000000000/"))}
}
